// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address alice, uint256 aliceAmt, address bob, uint256 bobAmt) public {
        vm.assume(alice != address(0) && bob != address(0) && alice != bob);
        aliceAmt = bound(aliceAmt, 1, type(uint96).max);
        bobAmt   = bound(bobAmt, 1, type(uint96).max);

        vm.deal(alice, aliceAmt);
        vm.prank(alice);
        c.addToBalance{value: aliceAmt}();

        vm.deal(bob, bobAmt);
        vm.prank(bob);
        c.addToBalance{value: bobAmt}();

        uint256 aliceBal = c.getBalance(alice);
        uint256 bobBal   = c.getBalance(bob);

        assertTrue(aliceBal == aliceAmt && bobBal == bobAmt);
    }
}
